style.css:
html, body, div, span, applet, object, iframe, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code, del, dfn, em, img, ins, 
kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, b, u, i, 
center, dl, dt, dd, ol, ul, li, fieldset, form, label, legend, table, 
caption, tbody, tfoot, thead, tr, th, td, article, aside, canvas, 
details, embed, figure, figcaption, footer, header, hgroup, menu, 
nav, output, ruby, section, summary, time, mark, audio, video {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
    border-color: #333333 !important;
}

/* Lighten interactive elements slightly for visibility */
input, textarea, select, button, a {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
    border: 1px solid #444444 !important;
}

/* Keep links readable */
a:link, a:visited {
    color: #3700b3 !important;
}
